"""Build an offline installer that patches a selected saved cockpit in place."""
from pathlib import Path
import re
r=Path(__file__).resolve().parent.parent
updater=(r/'Cockpit_OpenAI_Error_Updater.html').read_text()
code=re.search(r'<script>(.*?)</script>',updater,re.S)[1]
a=code.index("file.onchange=");code=code[:a] # reuse the verified pure code patch; replace the UI actions.
a=code.index("const file=document.getElementById('file')");b=code.index('\nfunction patch',a)
constants=code[a:b];constants=constants.replace("const file=document.getElementById('file'),button=document.getElementById('update'),status=document.getElementById('status'),", "const button=document.getElementById('update'),status=document.getElementById('status'),")
code=code[:a]+constants+code[b:]
ui='''<!DOCTYPE html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Save cockpit to the same file</title><style>body{font:16px/1.6 Arial,sans-serif;background:#f4f6f3;color:#21382a;margin:0;padding:22px}main{max-width:760px;margin:24px auto;background:white;padding:26px;border:1px solid #d9e2da;border-radius:14px}h1{font-size:25px;margin:0 0 14px}button{padding:12px 18px;border:0;border-radius:7px;background:#196b46;color:white;font-weight:bold;cursor:pointer;margin:8px 8px 8px 0}button:disabled{opacity:.5}#status{white-space:pre-wrap;overflow-wrap:anywhere;background:#f2f6f3;padding:12px;border-radius:8px}small{color:#5b6b60}</style></head><body><main><h1>Save to the same dashboard file</h1><p>This installs the saving adjustment into an existing cockpit HTML. It keeps that file’s name and location. Future <b>Save dashboard</b> and bottom <b>Save</b> update the linked master file; only <b>Download copy</b> deliberately creates another HTML.</p><ol><li>In your working cockpit, use <b>Save as copy</b> once to include any changes that exist only in the open tab. Keep the tab open, and pause its auto-save while updating.</li><li>Click <b>Choose master HTML and update it</b> below. Select that latest saved HTML in a local folder and allow editing.</li><li>After success, reopen that same HTML. Check your latest data. First Save may ask you to select the master file once; afterwards it updates that file.</li></ol><p>The selected file’s embedded data blocks are checked for exact preservation. Its previous version is retained in this browser before writing. No complaint or file is uploaded, and no API call is made.</p><button id="update">Choose master HTML and update it</button><button id="previous">Download previous file</button><p id="status" role="status">Ready. This changes a selected existing file, rather than downloading a new dashboard.</p><small>The browser’s file-editing permission is required to update one file. Keep a separate backup. If the dashboard contains work that has never been saved into its HTML, save that work before choosing a file here.</small></main><script>__CODE__
__ACTIONS__</script></body></html>'''
actions=r'''
const prevButton=document.getElementById('previous');let selected=null;
function installerDB(){return new Promise((resolve,reject)=>{const q=indexedDB.open('cockpit-same-file-installer-backups',1);q.onupgradeneeded=()=>q.result.createObjectStore('versions');q.onsuccess=()=>resolve(q.result);q.onerror=()=>reject(q.error);});}
async function keepPrevious(blob,name){const db=await installerDB();try{await new Promise((resolve,reject)=>{const tx=db.transaction('versions','readwrite'),st=tx.objectStore('versions'),get=st.get('latest');get.onsuccess=()=>{if(get.result)st.put(get.result,'older');st.put({blob,name,at:new Date().toISOString()},'latest');};tx.oncomplete=resolve;tx.onerror=()=>reject(tx.error);tx.onabort=()=>reject(tx.error||Error('Backup cancelled'));});}finally{db.close();}const checked=await getPrevious();if(checked?.blob?.size!==blob.size)throw Error('Could not verify the previous-file backup. No writer was opened.');}
async function getPrevious(){const db=await installerDB();try{return await new Promise((resolve,reject)=>{const q=db.transaction('versions').objectStore('versions').get('latest');q.onsuccess=()=>resolve(q.result);q.onerror=()=>reject(q.error);});}finally{db.close();}}
prevButton.onclick=async()=>{try{const old=await getPrevious();if(!old)throw Error('No previous file has been backed up by this updater yet.');const a=document.createElement('a'),url=URL.createObjectURL(old.blob);a.href=url;a.download=old.name.replace(/.html?$/i,'')+'_PREVIOUS.html';document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),30000);}catch(e){status.textContent=e.message;}};
async function install(handle){
 if(await handle.queryPermission({mode:'readwrite'})!=='granted'&&await handle.requestPermission({mode:'readwrite'})!=='granted')throw Error('Editing permission was not granted. Nothing was changed.');
 const before=await handle.getFile();if(!before.size)throw Error('The selected file is empty. Keep the working dashboard open and save its current data first.');
 const text=await before.text(),result=patch(text),output=new Blob([result.html],{type:'text/html'});
 // Retain a full previous version before opening a writer. Never read the source while writing.
 await keepPrevious(new Blob([text],{type:'text/html'}),handle.name);
 const checked=await handle.getFile();if(checked.size!==before.size||checked.lastModified!==before.lastModified)throw Error('The selected file changed during preparation. No writer was opened; retry with the correct master file.');
 const writer=await handle.createWritable();try{await writer.write(output);await writer.close();}catch(e){try{await writer.abort();}catch(_){}throw e;}
 const after=await handle.getFile();if(after.size!==output.size||await after.text()!==result.html)throw Error('The written file could not be verified. Keep the working tab open; Download previous file retrieves the backup.');
 return {name:handle.name,bytes:after.size,blocks:result.blocks};
}
window.CockpitSameFileInstaller={install,patch};
button.onclick=async()=>{if(typeof showOpenFilePicker!=='function'){status.textContent='This browser cannot edit files directly. Open this updater in current Edge or Chrome. No copy was created.';return;}button.disabled=true;try{const handles=await showOpenFilePicker({multiple:false,types:[{description:'Saved cockpit HTML',accept:{'text/html':['.html','.htm']}}]});selected=handles[0];status.textContent='Checking data and updating '+selected.name+'…';const result=await install(selected);status.textContent='Updated and verified: '+result.name+'\nSame file, same name. '+result.blocks+' embedded data blocks preserved.\nReopen this HTML. Both Save buttons now update a master file. On the first Save, select this same HTML if prompted and allow editing. No new dashboard was downloaded.';}catch(e){status.textContent=e.name==='AbortError'?'Cancelled. No file was changed and no copy was downloaded.':'Update failed: '+e.message+'\nKeep the working cockpit tab open. The previous-file backup is available if it was retained.';}finally{button.disabled=false;}};
'''
(r/'Cockpit_Save_To_Same_File_Updater.html').write_text(ui.replace('__CODE__',code).replace('__ACTIONS__',actions))
print('Built same-file updater')
